insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='oli'), 'Kapan Harus Ganti Oli? Panduan 2.000km untuk Motor Harian', 'kapan-ganti-oli', 'Jangan tunggu oli hitam pekat. Kenali tanda oli minta ganti dan risiko telat ganti oli.', 'Oli adalah darah motor. Untuk pemakaian harian Surabaya (macet + panas), ganti tiap 2000km atau 2 bulan. Cek warna, kekentalan, dan suara mesin. Telat ganti = mesin cepat panas, tarikan berat, dan keausan komponen.', '/motor3.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='rem'), 'Rem Berdecit? Ini Penyebab dan Cara Mengatasinya', 'rem-berdecit', 'Rem bunyi bukan sepele. Bisa kampas habis atau piringan kotor.', 'Cek kampas rem tiap 5000km. Jika berdecit, bersihkan piringan, cek ketebalan kampas, dan pastikan minyak rem cukup. Jangan rem mendadak saat kampas tipis.', '/motor1.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='ban'), 'Tekanan Angin Ban Ideal: Nyaman, Irit, Anti Selip', 'tekanan-ban-ideal', 'Ban kempes bikin boros bensin dan licin saat hujan.', 'Cek tekanan tiap 1 minggu. Depan 29-33 psi, belakang 33-36 psi tergantung beban. Ban botak = ganti, jangan ditambal terus.', '/motor3.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='cvt'), 'Servis CVT Matic: Biar Tarikan Enteng Tiap 8.000km', 'servis-cvt-matic', 'CVT kotor bikin gredek dan boros.', 'Bongkar CVT, bersihkan roller, vanbelt, kampas ganda. Ganti vanbelt tiap 20.000km. Jangan lupa cek grease.', '/motor4.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='aki'), 'Aki Soak? Kenali Tanda Sebelum Motor Mogok', 'aki-soak', 'Starter lemah dan lampu redup adalah sinyal aki minta perhatian.', 'Aki kering tahan 1.5-2 tahun. Cek voltase 12.4V+, bersihkan terminal, jangan biarkan motor lama tidak dinyalakan.', '/motor2.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='rantai'), 'Rantai Kendor Bikin Berisik? Setel Tiap 3.000km', 'rantai-kendor', 'Rantai kendor bikin tenaga hilang dan boros gear.', 'Setel kekencangan 20-30mm, lumasi tiap 500km, ganti gir set jika sudah tajam.', '/motor2.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='tips'), '5 Kebiasaan Bikin Motor Awet 10 Tahun', 'kebiasaan-motor-awet', 'Panaskan mesin 1 menit, jangan geber saat dingin, rutin cek oli.', 'Kebiasaan kecil berdampak besar. Servis berkala, cuci motor jangan semprot CVT langsung, parkir teduh.', '/motor2.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='pengetahuan'), 'Mengenal Komponen Motor: Dari CVT Hingga ECU', 'mengenal-komponen-motor', 'Paham istilah bengkel biar tidak bingung saat servis.', 'CVT = transmisi matic, ECU = otak injeksi, TB = throttle body. Paham dasar bikin tidak mudah ditipu.', '/motor4.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='faq'), 'FAQ: Berapa Biaya Servis Rutin Motor Matic?', 'faq-biaya-servis', 'Estimasi biaya servis ringan 150-300rb tergantung bengkel dan sparepart.', 'Servis ringan: oli + CVT bersih + cek rem. Servis berat: + ganti vanbelt + kampas + aki. Selalu minta rincian.', '/motor3.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='mesin'), 'Mesin Overheat di Macet Surabaya? Ini Solusinya', 'mesin-overheat', 'Radiator, oli, dan air coolant adalah kunci.', 'Jangan paksa jalan saat overheat. Menepi, matikan mesin 15 menit, cek coolant dan oli. Jika sering, cek thermostat.', '/motor1.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='kelistrikan'), 'Lampu Sering Putus? Cek Kiprok dan Aki', 'lampu-sering-putus', 'Kelistrikan tidak stabil merusak lampu dan ECU.', 'Cek kiprok/regulator, sekring, dan kabel. Ganti bohlam sesuai watt, jangan asal terang.', '/motor1.jpeg', true) on conflict (slug) do nothing;
insert into articles (category_id, title, slug, excerpt, content, cover_url, published) values ((select id from categories where slug='oli'), 'Oli Matic vs Manual: Jangan Salah Tuang', 'oli-matic-vs-manual', 'SAE dan JASO berbeda, salah oli bikin selip kopling.', 'Matic pakai JASO MB, manual pakai JASO MA. Cek SAE 10W-30 vs 10W-40 sesuai buku manual. Untuk katalog lengkap dengan harga bengkel, buka menu OLI.', '/motor2.jpeg', true) on conflict (slug) do nothing;
